# Draft 4 (23 Nov 2026): the ten checks PAP v5 section 4 listed in advance that draft 3 did not report (examiner draft 3, N1).
# Data through 30 June 2026 only (d2_common.load() asserts it). Writes <out>/numbers-pap.tex and <out>/numbers-pap-log.txt.
#   Robustness rows (PAP v5 line 72): December 2025 dropped; December year-end funds only; descriptions of 255+ characters dropped;
#     September 2025 mark bin x quarter effects; PIK controls off (headline has them on).
#     The first four reproduce the examiner's quick check of 18 Nov (qc_prereg.py) with the same code.
#   Exits (PAP v5 line 76): software x quarter on leaving the cohort and the worst-case (logical range) bound, read from
#     v2/results_exit_bounds_2026-11-08.txt, which v3_numbers.py regenerates on every run (stage 'exits').
#   Also reported (PAP v5 line 66): the 26-group rank with ITSV, DATA and HARD; the ranks of those three groups; a stricter comparison
#     without education, media and marketing; the plain coefficient rank; a loan-clustered t rank; the ratio to the next group; and the
#     Ferman and Pinto (2019) rescaling of the placebo statistics by group size.
# Usage: python3 d4_pap_numbers.py <draft4 folder>
import os as _os
_ROOT=_os.environ.get('THESIS_DATA',_os.path.abspath(_os.path.join(_os.path.dirname(__file__),'..','..','..')))  # repo root
import sys, os, re, time
sys.path.insert(0,(_ROOT+'/bdc/scripts/draft4'))
from d4_common import *
from d2_rank import NAMES
import statsmodels.formula.api as smf
OUT=sys.argv[1]; LOG=[]; t0=time.time()
def log(s): LOG.append(str(s)); print(s,flush=True)
p=CM.load(); assert p.ddate.max()==CM.JUN
keys=CM.cohort_keys(p); d0=CM.frozen(p,keys); d0['sw']=(d0.grp=='SOFT').astype(float)
S1='Step 1 headline spec (position + fund x quarter + vintage x quarter FE, borrower clusters), frozen cohort, model labels, June 2026'
def row(nm,tag,r):
    bm,sm=CM.get(r,'mark','2026-06'); bb,sb=CM.get(r,'b99','2026-06')
    putse4(f'Pap{tag}Mark',bm,sm,S1+'; '+nm); putse4(f'Pap{tag}Below',bb,sb,S1+'; '+nm,d=1); put4(f'Pap{tag}N',r['n']['pos'],'int',nm+', positions')
    log(f'[pap] {nm}: mark {bm:+.2f} ({sm:.2f}) | b99 {bb:+.1f} ({sb:.1f}) | positions {r["n"]["pos"]}')
r=CM.es(d0); row('headline (check)','Head',r)
row('December 2025 dropped','NoDec',CM.es(d0[d0.ddate!=CM.DEC]))
pos=pd.read_parquet(f'{CM.V}/positions.parquet',columns=['cik','ddate','form']); fye=pos[pos.form.str.startswith('10-K',na=False)].groupby('cik').ddate.agg(lambda s:s.dt.month.mode().iloc[0])
dec={c for c in fye[fye==12].index}; row('December year-end funds only','DecFye',CM.es(d0[d0.cik.isin(dec)]))
long_=set(d0.loc[(d0.ddate==CM.BASE)&(d0.ident.fillna('').str.len()>=255),'pkey']); put4('PapNLong',len(long_),'int','cohort positions with a description of 255+ characters')
row('descriptions of 255+ characters dropped','NoLong',CM.es(d0[~d0.pkey.isin(long_)]))
d0['mb']=pd.cut(d0.mark9,[-1,95,97,98,99,99.5,200],labels=False).astype(str)+'|'+d0.ddate.dt.strftime('%Y%m')
row('September 2025 mark bin x quarter effects','MarkBin',CM.es(d0,fe=('pkey','fq','vq','mb')))
rn=es_opts(d0,pik=False); bm,sm=rn['mark'].loc['2026-06']; bb,sb=rn['b99'].loc['2026-06']
putse4('PapNoPikMark',bm,sm,S1+'; PIK x quarter controls off'); putse4('PapNoPikBelow',bb,sb,S1+'; PIK controls off',d=1); log(f'[pap] PIK controls off: mark {bm:+.2f} ({sm:.2f}) | b99 {bb:+.1f} ({sb:.1f})')
rc=es_opts(d0,pik=True); assert abs(rc['mark'].loc['2026-06','b']-CM.get(r,'mark','2026-06')[0])<1e-9, 'es_opts copy does not reproduce es()'
# ---------------- exits (file regenerated by v3_numbers.py)
ex=open(f'{CM.V}/results_exit_bounds_2026-11-08.txt').read()
m=re.search(r'fund x quarter FE, borrower-clustered: 202512 ([-+0-9.]+) \(([0-9.]+)\); 202603 ([-+0-9.]+) \(([0-9.]+)\); 202606 ([-+0-9.]+) \(([0-9.]+)\)',ex)
putse4('PapExitJun',float(m.group(5)),float(m.group(6)),'software minus other, cumulative exit rate by June 2026 (pp), fund x quarter FE, borrower clusters',d=1)
w1=re.search(r'worst case for H1 \(software 110 / Below99 0; others 0 / 100\): mark 2026-03 [-+0-9.]+ \([0-9.]+\); 2026-06 ([-+0-9.]+) \([0-9.]+\) \| b99 2026-03 [-+0-9.]+ \([0-9.]+\); 2026-06 ([-+0-9.]+)',ex)
w2=re.search(r'worst case against H1 reversed \(software 0 / 100; others 110 / 0\): mark 2026-03 [-+0-9.]+ \([0-9.]+\); 2026-06 ([-+0-9.]+) \([0-9.]+\) \| b99 2026-03 [-+0-9.]+ \([0-9.]+\); 2026-06 ([-+0-9.]+)',ex)
put4('PapWorstMarkHi',float(w1.group(1)),'f2','worst-case exit bound, June mark, leavers software 110 / others 0',sign=True); put4('PapWorstMarkLo',float(w2.group(1)),'f2','worst case reversed',sign=True)
put4('PapWorstBelowLo',float(w1.group(2)),'f1','worst-case exit bound, June Below99, software leavers 0 / others 100',sign=True); put4('PapWorstBelowHi',float(w2.group(2)),'f1','reversed',sign=True)
log('[pap] exits: '+m.group(0)+' | worst case mark ['+w2.group(1)+', '+w1.group(1)+'] b99 ['+w1.group(2)+', '+w2.group(2)+']')
# ---------------- ranks
ch=changes(p)
base=rank_table(ch);
for y,Y in [('db99','Below'),('dmark','Mark')]:
    rk,n,t=rank_of(base,y); assert rk==1 and n==23
    nx=t[t.grp!='SOFT'].iloc[0]; s=float(t.loc[t.grp=='SOFT','T'].iloc[0]); put4(f'PapRatio{Y}',s/float(nx['T']),'f1',f'software scaled statistic / next group, {y}')
    rk2,_,t2=rank_of(base,y,col='post'); put4(f'PapRankPlain{Y}',rk2,'int',f'software rank on the unscaled Dec25-Jun26 sum, 23 groups, {y}')
    top=t2.iloc[0]; put4(f'PapPlainTop{Y}Name',NAMES[top.grp].lower(),'str','group first on the unscaled sum'); put4(f'PapPlainTop{Y}',float(top.post),'f2' if y=='dmark' else 'f1','its unscaled Dec25-Jun26 sum',sign=True)
    put4(f'PapPlainSw{Y}',float(t2.loc[t2.grp=='SOFT','post'].iloc[0]),'f2' if y=='dmark' else 'f1','software unscaled sum',sign=True)
    put4(f'PapPlainTopSd{Y}',float(top.sd),'f2','pre-period SD of the first group'); put4(f'PapPlainSwSd{Y}',float(t2.loc[t2.grp=='SOFT','sd'].iloc[0]),'f2','pre-period SD of software')
    log(f'[pap] 23 groups {y}: software {s:+.2f}, next {nx.grp} {nx["T"]:+.2f}; plain coefficient rank {rk2}; plain top '+'; '.join(f'{r.grp} {r.post:+.2f} (sd {r.sd:.2f}, M {r.M:.0f})' for _,r in t2.head(4).iterrows()))
g26=rank_table(ch,drop=('UNKN','FUND'))
for y,Y in [('db99','Below'),('dmark','Mark')]:
    rk,n,t=rank_of(g26,y); put4(f'PapRankTwentySix{Y}',rk,'int',f'software rank among {n} groups incl. ITSV DATA HARD, {y}'); put4('PapNTwentySix',n,'int','groups') if Y=='Below' else None
    for g,G in [('ITSV','Itsv'),('DATA','Data'),('HARD','Hard')]:
        put4(f'PapRank{G}{Y}',rank_of(g26,y,g)[0],'int',f'rank of {g} among {n} groups, {y}')
    log(f'[pap] 26 groups {y}: '+'; '.join(f'{r.grp} {r["T"]:+.2f}' for _,r in t.head(6).iterrows()))
st=rank_table(ch,drop=('UNKN','FUND','ITSV','DATA','HARD','EDUC','MEDI','MKTG'))
for y,Y in [('db99','Below'),('dmark','Mark')]:
    rk,n,t=rank_of(st,y); put4(f'PapRankStrict{Y}',rk,'int',f'software rank, stricter comparison without EDUC MEDI MKTG, {y}'); put4('PapNStrict',n,'int','groups') if Y=='Below' else None
    log(f'[pap] strict {n} groups {y}: rank {rk}')
# loan-clustered t rank: June change on a group dummy, fund effects, positions of the frozen cohort held at both dates (software out of the pool for other groups)
s9=d0[d0.ddate==CM.BASE].set_index('pkey'); j=d0[d0.ddate==CM.JUN].set_index('pkey')
cx=s9[['cik','grp','loan']].join((j.mark-s9.mark).rename('dmark'),how='inner').join((j.b99-s9.b99).rename('db99'))
cx=cx[~cx.grp.isin(['UNKN','FUND','ITSV','DATA','HARD'])]
tr=[]
for gname in sorted(cx.grp.unique()):
    x=cx if gname=='SOFT' else cx[cx.grp!='SOFT']; x=x.assign(g=(x.grp==gname).astype(float),f=x.cik.astype(str))
    for y in ['dmark','db99']:
        xx=x.dropna(subset=[y,'loan']).copy(); xx['yd']=xx[y]-xx.groupby('f')[y].transform('mean'); xx['gd']=xx.g-xx.groupby('f').g.transform('mean')
        mm=smf.ols('yd~gd-1',xx).fit(cov_type='cluster',cov_kwds={'groups':pd.factorize(xx.loan)[0]}); tr.append(dict(grp=gname,y=y,T=mm.tvalues.iloc[0]))
TR=pd.DataFrame(tr)
for y,Y in [('db99','Below'),('dmark','Mark')]:
    rk,n,t=rank_of(TR,y); put4(f'PapRankT{Y}',rk,'int',f'software rank on the loan-clustered t of the Sep25-Jun26 change, fund effects, {n} groups, {y}')
    log(f'[pap] t rank {y}: rank {rk} of {n}; top '+'; '.join(f'{r.grp} {r["T"]:+.1f}' for _,r in t.head(4).iterrows()))
# Ferman and Pinto (2019): placebo statistics rescaled by the estimated var(W|M) = A + B/M across the 22 control groups (M = positions per quarter)
for y,Y in [('db99','Below'),('dmark','Mark')]:
    x=base[base.y==y].set_index('grp'); a=x['post']; M=x['M']; ctrl=[g for g in x.index if g!='SOFT']
    X=np.column_stack([np.ones(len(ctrl)),1/M[ctrl].values]); coef=np.linalg.lstsq(X,(a[ctrl]**2).values,rcond=None)[0]
    v=lambda m: max(coef[0]+coef[1]/m,1e-12)
    resc=pd.Series({g:a[g]*np.sqrt(v(M['SOFT'])/v(M[g])) for g in ctrl})
    exg=resc[resc>=a['SOFT']] if y=='db99' else resc[resc<=a['SOFT']]; ext=len(exg)
    if ext: put4(f'PapFpExtName{Y}',', '.join(NAMES[g].lower() for g in exg.index),'str','rescaled placebo(s) at least as extreme')
    log(f'[pap] FP {y}: rescaled placebos sorted: '+'; '.join(f'{g} {v:+.2f} (M {M[g]:.0f}, raw {a[g]:+.2f})' for g,v in resc.sort_values(ascending=(y=='dmark')).head(5).items()))
    pval=(1+ext)/(len(ctrl)+1); put4(f'PapFp{Y}',pval,'f3',f'Ferman-Pinto rescaled placebo p-value, one-sided, {y}'); put4(f'PapFpExt{Y}',int(ext),'int','rescaled placebos at least as extreme')
    put4(f'PapFpA{Y}',coef[0],'f3','A in var=A+B/M'); put4(f'PapFpB{Y}',coef[1],'f2','B in var=A+B/M')
    log(f'[pap] Ferman-Pinto {y}: software {a["SOFT"]:+.2f} (M {M["SOFT"]:.0f}); A {coef[0]:.4f} B {coef[1]:.3f}; rescaled placebo range {resc.min():+.2f}..{resc.max():+.2f}; extreme {ext}; p {pval:.3f}')
h=write_macros(f'{OUT}/numbers-pap.tex','% numbers-pap.tex: PAP v5 checks listed in advance (examiner N1). Written by bdc/scripts/draft4/d4_pap_numbers.py. Data to 30 June 2026.\n')
write_log(f'{OUT}/numbers-pap-log.txt',f'd4_pap_numbers.py run {time.strftime("%Y-%m-%d %H:%M UTC",time.gmtime())}, {time.time()-t0:.0f} s, numbers-pap.tex sha256 {h[:16]}',LOG)
print('numbers-pap.tex sha256',h)
